/// @custom:version 1.0.0
interface IGlacisAirlift {
    /// @notice Registers function selectors to multiple token. A selector's function must be added to the Diamond as a facet.
    /// @param diamondSelectors The bytes4 selector of the token's handler function.
    /// @param facetSelectors The bytes4 selector of the token's handler function.
    /// @param token The token to register.
    function addSelectorsToToken(bytes4[] memory diamondSelectors, bytes4[] memory facetSelectors, address token)
        external;

    /// @notice Use to send a token from chain A to chain B after sending this contract the token already.
    /// This function should only be used when a smart contract calls it, so that the token's transfer
    /// and the cross-chain send are atomic within a single transaction.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    /// @param receiver The target address that should receive the funds on the destination chain.
    /// @param destinationChainId The Ethereum chain ID of the destination chain.
    /// @param refundAddress The address that should receive any funds in the case the cross-chain gas value is too high.
    /// @return sendResponse The response from the token's handler function: not standardized.
    function send(address token, uint256 amount, bytes32 receiver, uint256 destinationChainId, address refundAddress)
        external
        payable
        returns (bytes memory);

    /// @notice Use to send a token from chain A to chain B after only approving this contract to transfer the tokens.
    /// This function should be used by EOAs who want to do the approval and transaction in two separate blocks.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    /// @param receiver The target address that should receive the funds on the destination chain.
    /// @param destinationChainId The Ethereum chain ID of the destination chain.
    /// @param refundAddress The address that should receive any funds in the case the cross-chain gas value is too high.
    /// @return sendResponse The response from the token's handler function: not standardized.
    function sendAfterApproval(
        address token,
        uint256 amount,
        bytes32 receiver,
        uint256 destinationChainId,
        address refundAddress
    ) external payable returns (bytes memory);

    /// @notice Use to quote the send a token from chain A to chain B.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    /// @param receiver The target address that should receive the funds on the destination chain.
    /// @param destinationChainId The Ethereum chain ID of the destination chain.
    /// @param refundAddress The address that should receive any funds in the case the cross-chain gas value is too high.
    /// @return The amount of token and value fees required to send the token across chains.
    function quoteSend(
        address token,
        uint256 amount,
        bytes32 receiver,
        uint256 destinationChainId,
        address refundAddress,
        uint256 msgValue
    ) external returns (QuoteSendInfo memory);
}

// src/facets/FeeControllerFacet.sol

using SafeERC20 for IERC20;

/// @title Fee Controller Facet
/// @author Glacis (https://glacislabs.com)
/// @notice Manages fees for the Airlift protocol.
/// @custom:version 1.0.0
contract FeeControllerFacet {
    error FeeControllerFacet__TokenAndConfigLengthsAreNotEqual();
    error FeeControllerFacet__BPSTooHigh();

    struct FeeControllerFacetStorage {
        mapping(address baseToken => FeeForTokenTransfer fees) tokenToFee;
        address feeCollector;
        FeeForTokenTransfer defaultFee;
    }

    struct FeeForTokenTransfer {
        /// The flat amount we take from the value.
        uint120 valueAmnt;
        /// True if we take a percentage of the token, false if it's a flat amount.
        bool takeTokenBps;
        /// The token amount or BPS we take from the value
        uint120 tokenAmnt;
        /// True if the fee is explicitly zero, false otherwise. If this is false and the values are 0, the default fee will be used.
        bool isZero;
    }

    bytes32 constant STORAGE_POSITION = keccak256("Airlift.FeeControllerFacet.Storage");

    /// @notice Get the storage relevant to the Fee Controller Facet
    /// @return facetStorage The storage for the Fee Controller Facet
    function _getFeeControllerFacetStorage() internal pure returns (FeeControllerFacetStorage storage facetStorage) {
        bytes32 _STORAGE_POSITION = STORAGE_POSITION;
        assembly {
            facetStorage.slot := _STORAGE_POSITION
        }
    }

    /// @notice Configures the entire fee controller.
    /// @param tokens The array of tokens to configure.
    /// @param configs The array of configs to configure for said tokens.
    /// @param collector The fee collector.
    function configureFeeFacet(
        address[] memory tokens,
        FeeForTokenTransfer[] memory configs,
        FeeForTokenTransfer memory defaultFee,
        address collector
    ) external {
        // The base address or Enforce contract owner
        if (msg.sender != address(this)) LibDiamond.enforceIsContractOwner();

        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();

        facetStorage.feeCollector = collector;
        facetStorage.defaultFee = defaultFee;
        feeControllerSetTokenConfig(tokens, configs);
    }

    /// @notice Sets fee configs for certain tokens.
    /// @param tokens The array of tokens to configure.
    /// @param configs The array of configs to configure for said tokens.
    function feeControllerSetTokenConfig(address[] memory tokens, FeeForTokenTransfer[] memory configs) public {
        LibDiamond.enforceIsContractOwner();
        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();

        uint256 len = tokens.length;
        if (len != configs.length) {
            revert FeeControllerFacet__TokenAndConfigLengthsAreNotEqual();
        }

        for (uint256 i; i < len; ++i) {
            FeeForTokenTransfer memory c = configs[i];
            if (c.takeTokenBps && c.tokenAmnt > 10_000) {
                revert FeeControllerFacet__BPSTooHigh();
            }

            facetStorage.tokenToFee[tokens[i]] = c;
        }
    }

    /// @notice Transfers the fee tokens and value to the collector address.
    /// @param tokens The address of the tokens to collect.
    function collect(address[] memory tokens) public {
        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();
        address collector = facetStorage.feeCollector;
        // Forward value fee to fee address
        SafeTransferLib.safeTransferETH(collector, address(this).balance);

        // Forward tokens to fee address
        uint256 len = tokens.length;
        for (uint256 i; i < len; ++i) {
            IERC20(tokens[i]).safeTransfer(collector, IERC20(tokens[i]).balanceOf(address(this)));
        }
    }

    /// Returns the token and value fees for a given token and amount.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    function getAirliftFee(address token, uint256 amount) public view returns (Fee memory) {
        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();
        FeeForTokenTransfer memory config = facetStorage.tokenToFee[token];
        if (config.isZero) {
            return Fee(0, 0);
        } else if (config.tokenAmnt + config.valueAmnt == 0) {
            config = facetStorage.defaultFee;
        }

        uint256 valueFee = config.valueAmnt;
        uint256 tokenFee;

        if (config.takeTokenBps) {
            // Token fee should never be above 100%, due to protections in feeControllerSetTokenConfig
            tokenFee = (amount * uint256(config.tokenAmnt)) / 10_000;
        } else {
            tokenFee = config.tokenAmnt;
        }

        return Fee(valueFee, tokenFee);
    }

    /// @notice Returns the fee configuration set for a token.
    /// @param token The address of the token sending across chains.
    function getAirliftFeeConfig(address token) external view returns (FeeForTokenTransfer memory) {
        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();
        return facetStorage.tokenToFee[token];
    }

    /// @notice Returns the fee collector address.
    /// @return The address of the fee collector.
    function getAirliftFeeCollector() external view returns (address) {
        FeeControllerFacetStorage storage facetStorage = _getFeeControllerFacetStorage();
        return facetStorage.feeCollector;
    }

    /// @notice Returns the fees and resultant amount of tokens & value available after the fees are removed.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    /// @param value The value sent with the transaction.
    function getCorrectedAmounts(address token, uint256 amount, uint256 value)
        external
        view
        returns (AirliftFeeInfo memory)
    {
        uint256 correctedValue;
        uint256 correctedAmount = IERC20(token).balanceOf(address(this)); // Token arrived at Airlift could be less than requested because it is a fee on transfer ERC20
        if (correctedAmount > amount) correctedAmount = amount;

        // Ensure fee
        Fee memory airliftFee = getAirliftFee(token, amount);
        if (value < airliftFee.nativeFee) {
            revert GlacisAirlift__NotEnoughValueFee();
        } else {
            correctedValue = value - airliftFee.nativeFee;
        }
        if (correctedAmount < airliftFee.tokenFee) {
            revert GlacisAirlift__NotEnoughTokenFee();
        } else {
            correctedAmount = correctedAmount - airliftFee.tokenFee;
        }
        return AirliftFeeInfo(airliftFee, correctedAmount, correctedValue);
    }

    /// @notice Returns the fees and resultant amount of tokens & value available after the fees are removed when quoting.
    /// @param token The address of the token sending across chains.
    /// @param amount The amount of the token you want to send across chains.
    /// @param value The value sent with the transaction.
    function getCorrectedAmountsForQuote(address token, uint256 amount, uint256 value)
        external
        view
        returns (AirliftFeeInfo memory)
    {
        uint256 correctedValue;
        uint256 correctedAmount = amount;
        // Ensure fee
        Fee memory airliftFee = getAirliftFee(token, amount);
        if (value < airliftFee.nativeFee) {
            revert GlacisAirlift__NotEnoughValueFee();
        } else {
            correctedValue = value - airliftFee.nativeFee;
        }
        if (correctedAmount < airliftFee.tokenFee) {
            revert GlacisAirlift__NotEnoughTokenFee();
        } else {
            correctedAmount = correctedAmount - airliftFee.tokenFee;
        }
        return AirliftFeeInfo(airliftFee, correctedAmount, correctedValue);
    }
}
